}

#include <stdio.h>
#include <stdbool.h>

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

int main() {
    int n = 29;
    printf("%d is %s\n", n, isPrime(n) ? "Prime" : "Not Prime");
    return 0;
}

#include <stdio.h>
#include <math.h>

int isArmstrong(int n) {
    int orig = n, digits = 0, sum = 0, temp = n;
    while (temp > 0) { digits++; temp /= 10; }
    temp = n;
    while (temp > 0) {
        sum += (int)pow(temp % 10, digits);
        temp /= 10;
    }
    return sum == orig;
}

int main() {
    int n = 153;
    printf("%d is %s\n", n, isArmstrong(n) ? "Armstrong" : "Not Armstrong");
    return 0;
}

